function xtra_ignore_activation()
{
    $a = get_option("codevz_theme_activation", ["type" => ""]);
    if ($a["type"] !== "rtltheme") {
        update_option("codevz_theme_activation", ["type" => "rtltheme", "item_id" => "xtra", "purchase_code" => "rtltheme", "purchase_date" => "01-01-2020", "support_until" => "01-01-2030"]);
    }
}
function xtra_dashboard_activation_not_active()
{
    message("error", esc_html__("Your theme is not activated.", "xtra"));
    echo "<p style=\"margin-bottom:30px\">" . esc_html__("For access to all theme features, please activate your theme.", "xtra") . "</p>";
    echo "<div class=\"xtra_rtl_buttons_wrap\"><a target=_blank href=\"https://www.rtl-theme.com/xtra-corporate-woocommerce-theme/\" class=\"xtra-button-primary\" ><span>" . esc_html__("Buy Xtra Theme", "xtra") . "</span></a>";
    echo "<a target=_blank href=\"https://www.rtl-theme.com/products-license-status-deactivate/\" style=\"margin:0 15px;\" class=\"xtra-button-secondary\" ><span>" . esc_html__("Activation Help", "xtra") . "</span></a></div>";
}
function xtra_dashboard_activation_active()
{
    echo "<h1>" . esc_html__("Congratulation", "xtra") . "</h1></br></br>";
    message("success", esc_html__("Your theme has been activated successfully.", "xtra"));
}
function message($type, $message)
{
    $icon = $type === "error" ? "no-alt" : ($type === "info" ? "info-outline" : "saved");
    echo "<div class=\"xtra-dashboard-" . esc_attr($type) . "\"><i class=\"dashicons dashicons-" . esc_attr($icon) . "\"></i><span>" . wp_kses_post($message) . "</span></div>";
}
function xtra_rtl_checkbox()
{
    return "<label class=\"xtra-checkbox xtra-rtl\" data-tooltip=\"" . esc_html__("By checking this field, wizard will import English version of current demo that you have selected.", "xtra") . "\">" . esc_html__("English version?", "xtra") . "<input type=\"checkbox\" name=\"rtl\" /><span class=\"checkmark\"></span></label>";
}
function xtra_rtl_checker()
{
    $folder = !is_rtl() && !isset($args["rtl"]) ? "rtl/" : "";
    return $folder;
}
function xtra_rtl_preview($preview)
{
    if (is_rtl()) {
        $preview = str_replace("arabic/", "", $preview);
    } else {
        $preview = str_replace(".ir", ".com", $preview);
    }
    return $preview;
}
function xtra_rtl_plugins($arg)
{
    $arg["wp-parsidate"] = ["name" => esc_html__("Parsi Date", "xtra"), "recommended" => true, "class_exists" => "WP_Parsidate"];
    $arg["persian-woocommerce"] = ["name" => esc_html__("Persian Woocommerce", "xtra"), "recommended" => true, "function_exists" => "PW"];
    $arg["rtl-theme"] = ["name" => esc_html__("RTL Theme Updater", "xtra"), "recommended" => true, "source" => Codevz_Core_Theme::$api . "rtl-theme.zip", "function_exists" => "rtl_theme_admin_enqueue_scripts"];
    return $arg;
}
